export const CreateStudioArtworkBody = zod.object({
  "title": zod.string().min(1).max(createStudioArtworkBodyTitleMax),
  "year": zod.string().max(createStudioArtworkBodyYearMax).optional(),
  "dimensions": zod.string().max(createStudioArtworkBodyDimensionsMax).optional(),
  "medium": zod.string().min(1).max(createStudioArtworkBodyMediumMax),
  "price": zod.string().max(createStudioArtworkBodyPriceMax).optional(),
  "availability": zod.enum(['Available', 'Reserved', 'Sold', 'Not for sale']).optional(),
  "notes": zod.string().max(createStudioArtworkBodyNotesMax).optional(),
  "seoTitle": zod.string().max(createStudioArtworkBodySeoTitleMax).optional(),
  "seoDescription": zod.string().max(createStudioArtworkBodySeoDescriptionMax).optional(),
  "seoKeywords": zod.array(zod.string().min(1).max(createStudioArtworkBodySeoKeywordsItemMax)).max(createStudioArtworkBodySeoKeywordsMax).optional(),
  "photos": zod.array(zod.object({
  "name": zod.string().min(1).max(createStudioArtworkBodyPhotosItemNameMax),
  "objectPath": zod.string().regex(createStudioArtworkBodyPhotosItemObjectPathRegExp)
})).min(1).max(createStudioArtworkBodyPhotosMax)
})

export const CreateStudioArtworkResponse = zod.object({
  "artwork": zod.object({
  "id": zod.string(),
  "title": zod.string(),
  "seoTitle": zod.string(),
  "seoDescription": zod.string(),
  "seoKeywords": zod.array(zod.string()),
  "year": zod.string(),
  "dimensions": zod.string(),
  "medium": zod.string(),
  "price": zod.string(),
  "availability": zod.enum(['Available', 'Reserved', 'Sold', 'Not for sale']),
  "notes": zod.string(),
  "photos": zod.array(zod.object({
  "name": zod.string(),
  "objectPath": zod.string(),
  "src": zod.string().url()
})),
  "readiness": zod.enum(['Needs details', 'Ready for review', 'In review']),
  "destinations": zod.object({
  "website": zod.enum(['Not prepared', 'Prepared']),
  "store": zod.enum(['Not prepared', 'Prepared']),
  "social": zod.enum(['Not prepared', 'Prepared']),
  "newsletter": zod.enum(['Not prepared', 'Prepared']),
  "marketplaces": zod.enum(['Not prepared', 'Prepared'])
}),
  "updatedAt": zod.coerce.date()
}),
  "pinterest": zod.object({
  "status": zod.string(),
  "message": zod.string()
})
})


/**
 * @summary List durable artwork Pinterest publishing records
 */
export const ListStudioArtworkPinterestResponseItem = zod.object({
  "artworkId": zod.string(),
  "title": zod.string(),
  "status": zod.enum(['queued', 'publishing', 'published', 'failed']),
  "pinterestPinId": zod.string().nullable(),
  "attempts": zod.number().int(),
  "lastError": zod.string().nullable(),
  "publishedAt": zod.coerce.date().nullable(),
  "updatedAt": zod.coerce.date()
})
export const ListStudioArtworkPinterestResponse = zod.array(ListStudioArtworkPinterestResponseItem)


/**
 * @summary Retry Pinterest publishing for an artwork
 */
export const RetryStudioArtworkPinterestParams = zod.object({
  "id": zod.coerce.string()
})

export const RetryStudioArtworkPinterestResponse = zod.object({
  "status": zod.enum(['queued', 'publishing', 'published', 'failed']),
  "pinterestPinId": zod.string().nullish()
})


/**
 * @summary Complete the Pinterest OAuth flow
 */
export const PinterestOAuthCallbackQueryParams = zod.object({
  "code": zod.coerce.string().optional(),
  "state": zod.coerce.string(),
  "error": zod.coerce.string().optional()
})

export const PinterestOAuthCallbackResponse = zod.void()


/**
 * @summary Return the current Pinterest connection status
 */
export const GetPinterestStatusResponse = zod.object({
  "connected": zod.boolean(),
  "username": zod.string().nullable(),
  "expiresAt": zod.coerce.date().nullable()
})


/**
 * @summary List boards from the connected Pinterest account
 */
export const ListPinterestBoardsResponse = zod.object({
  "boards": zod.array(zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "description": zod.string(),
  "privacy": zod.string(),
  "pinCount": zod.number().int()
}))
})


/**
 * @summary Create any missing Studio OS boards in Pinterest
 */
export const syncPinterestBoardsBodyBoardsItemNameMax = 100;

export const syncPinterestBoardsBodyBoardsItemDescriptionMax = 500;

export const syncPinterestBoardsBodyBoardsMax = 20;



export const SyncPinterestBoardsBody = zod.object({
  "boards": zod.array(zod.object({
  "name": zod.string().min(1).max(syncPinterestBoardsBodyBoardsItemNameMax),
  "description": zod.string().max(syncPinterestBoardsBodyBoardsItemDescriptionMax).optional()
})).min(1).max(syncPinterestBoardsBodyBoardsMax)
})

export const SyncPinterestBoardsResponse = zod.object({
  "boards": zod.array(zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "description": zod.string(),
  "privacy": zod.string(),
  "pinCount": zod.number().int()
}))
})


/**
 * @summary Publish one approved Pin to Pinterest
 */
export const publishPinterestPinBodyBoardIdMax = 120;

export const publishPinterestPinBodyTitleMax = 100;

export const publishPinterestPinBodyDescriptionMax = 500;

export const publishPinterestPinBodyAltTextMax = 500;



export const PublishPinterestPinBody = zod.object({
  "boardId": zod.string().min(1).max(publishPinterestPinBodyBoardIdMax),
  "title": zod.string().min(1).max(publishPinterestPinBodyTitleMax),
  "description": zod.string().max(publishPinterestPinBodyDescriptionMax),
  "altText": zod.string().max(publishPinterestPinBodyAltTextMax),
  "link": zod.string().url(),
  "imageUrl": zod.string().url()
})

export const PublishPinterestPinResponse = zod.object({
  "id": zod.string().nullable(),
  "status": zod.enum(['published'])
})


/**
 * @summary Remove the stored Pinterest connection
 */
export const DisconnectPinterestResponse = zod.object({
  "ok": zod.boolean()
})


